const resultBatchSize = 12
const uiStateStorageKey = 'card-vault-ui-state-v1'
const createNewDeckValue = '__new__'
const appTabs: AppTab[] = ['scan', 'mtg', 'pokemon']
const gameFilters: GameFilter[] = ['mtg', 'pokemon']
const collectionGroups: CollectionGroup[] = ['color', 'set', 'condition', 'category']
const collectionSorts: CollectionSort[] = ['name', 'value', 'quantity', 'newest']

const conditions: Condition[] = [
  'Near Mint',
  'Lightly Played',
  'Moderately Played',
  'Heavily Played',
  'Damaged',
]
const defaultCondition: Condition = 'Near Mint'
let cachedPersistedUiState: PersistedUiState | null = null

function getPersistedUiState(): PersistedUiState {
  if (!cachedPersistedUiState) {
    cachedPersistedUiState = readPersistedUiState()
  }

  return cachedPersistedUiState
}

function readPersistedUiState(): PersistedUiState {
  if (typeof window === 'undefined') {
    return {}
  }

  try {
    const rawState = window.localStorage.getItem(uiStateStorageKey)

    if (!rawState) {
      return {}
    }

    const parsed = JSON.parse(rawState) as unknown

    if (!isPlainObject(parsed)) {
      return {}
    }

    const state: PersistedUiState = {}

    if (isOneOf(parsed.activeTab, appTabs)) {
      state.activeTab = parsed.activeTab
    }

    if (isOneOf(parsed.game, gameFilters)) {
      state.game = parsed.game
    }

    if (isOneOf(parsed.collectionGroup, collectionGroups)) {
      state.collectionGroup = parsed.collectionGroup
    }

    if (isOneOf(parsed.collectionSort, collectionSorts)) {
      state.collectionSort = parsed.collectionSort
    }

    if (isStringBooleanRecord(parsed.collapsedGroups)) {
      state.collapsedGroups = parsed.collapsedGroups
    }

    return state
  } catch {
    return {}
  }
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value)
}

function isOneOf<T extends string>(value: unknown, options: T[]): value is T {
  return typeof value === 'string' && options.includes(value as T)
}

function isSupportedGame(value: unknown): value is GameFilter {
  return isOneOf(value, gameFilters)
}

function isStringBooleanRecord(value: unknown): value is Record<string, boolean> {
  if (!isPlainObject(value)) {
    return false
  }

  return Object.values(value).every((item) => typeof item === 'boolean')
}

