  async function synchronizeSession(
    session: AccountSession,
    announce: boolean,
  ) {
    if (accountSyncRunningRef.current) {
      return
    }

    accountSyncRunningRef.current = true
    if (announce) {
      setAccountStatus('Syncing collection and decks.')
    }

    try {
      const result = await synchronizeAccount(session)
      if (result.changed) {
        await Promise.all([loadCollection(), loadDeckData()])
      }
      setAccountStatus(
        result.conflicts
          ? 'Synced. A newer change from another device was kept.'
          : 'Collection and decks synced.',
      )
    } catch {
      setAccountStatus('Offline. Changes are safe on this device and will sync later.')
    } finally {
      accountSyncRunningRef.current = false
    }
  }

  function updateAccountDraft(values: Partial<AccountDraft>) {
    setAccountDraft((current) => ({ ...current, ...values }))
  }

  async function submitAccount() {
    if (accountDraft.isSaving) {
      return
    }

    const username = accountDraft.username.trim()
    const displayName = accountDraft.displayName.trim()
    if (!username || !accountDraft.password) {
      setAccountStatus('Username and password are required.')
      return
    }
    if (accountMode === 'create' && accountDraft.password.length < 5) {
      setAccountStatus('Use at least 5 characters for the password.')
      return
    }

    updateAccountDraft({ isSaving: true })
    setAccountStatus(accountMode === 'create' ? 'Creating profile.' : 'Signing in.')

    try {
      const session =
        accountMode === 'create'
          ? await createAccount(
              username,
              displayName,
              accountDraft.password,
              accountDraft.remember,
            )
          : await loginAccount(
              username,
              accountDraft.password,
              accountDraft.remember,
            )
      await prepareAccountData(session.profile.id)
      setAccountSession(session)
      await synchronizeSession(session, true)
      accountSyncReadyRef.current = true
      setAccountDraft((current) => ({ ...current, password: '', isSaving: false }))
      setAccountDialogOpen(false)
      setStatus(`Signed in as ${session.profile.displayName}`)
    } catch (error) {
      setAccountStatus(
        error instanceof Error ? error.message : 'Could not open this profile.',
      )
      updateAccountDraft({ isSaving: false })
    }
  }

  async function signOutAccount() {
    const session = accountSession
    if (!session) {
      return
    }

    await synchronizeSession(session, false)
    accountSyncReadyRef.current = false
    await logoutAccount(session)
    setAccountSession(null)
    setAccountMode('login')
    setAccountDraft((current) => ({
      ...current,
      password: '',
      isSaving: false,
    }))
    setAccountStatus('Signed out. Your profile data remains saved.')
    setAccountDialogOpen(true)
  }

  async function runSearch(searchTerm = query): Promise<number> {
    const cleanTerm = searchTerm.trim()

    if (!cleanTerm) {
      setStatus('Type a card name or scan one first.')
      return 0
    }

    setIsSearching(true)
    setCandidates([])
    setSelectedTerm(cleanTerm)
    setResultOffset(0)
    setHasMoreResults(false)
    setStatus(`Searching for "${cleanTerm}"`)

    try {
      const results = await searchCards(game, cleanTerm, {
        limit: resultBatchSize,
        offset: 0,
      })
      setCandidates(results)
      setSelectedTerm(cleanTerm)
      setHasMoreResults(results.length >= resultBatchSize)
      setStatus(results.length ? `${results.length} possible matches` : 'No matches found')
      return results.length
    } catch {
      setStatus('Search failed. Check your connection and try again.')
      return 0
    } finally {
      setIsSearching(false)
    }
  }

  async function runAutoSearch(
    terms: string[],
    scanResult?: ScanResult,
    capturedCard?: HTMLCanvasElement,
  ): Promise<{ count: number; term: string; results: CardCandidate[] }> {
    const reportedWrongPrintingId =
      game === 'mtg'
        ? terms
            .map((term) => mtgReportedWrongPrintingIds[normalizeName(term)])
            .find(Boolean)
        : undefined
    const maxAutoTerms = game === 'pokemon' ? 4 : 7
    const reportedCorrections = terms
      .map((term) =>
        game === 'mtg'
          ? mtgReportedNameCorrections[normalizeName(term)]
          : game === 'pokemon'
            ? pokemonReportedNameCorrections[normalizeName(term)]
            : undefined,
      )
      .filter((term): term is string => Boolean(term))
    const cleanTerms = Array.from(
      new Set(
        [
          ...reportedCorrections,
          ...terms.flatMap((term) => expandOcrSearchTerms(term, game)),
        ]
          .map((term) => term.trim())
          .filter((term) => isAutoTermWorthSearching(term, game)),
      ),
    ).slice(0, maxAutoTerms)

    if (!cleanTerms.length) {
      return { count: 0, term: '', results: [] }
    }

    setIsSearching(true)

    try {
      let best:
        | {
            results: CardCandidate[]
            term: string
          }
        | null = null

      for (const term of cleanTerms) {
        setStatus(`Checking "${term}"`)

        const results = await searchCards(game, term, {
          limit: resultBatchSize,
          offset: 0,
        })

        if (!results.length) {
          continue
        }

        const matchingResults = results.filter((card) => namesLikelyMatch(term, card.name))

        if (!matchingResults.length) {
          continue
        }

        best = { results: matchingResults, term }
        break
      }

      if (!best) {
        setCandidates([])
        return { count: 0, term: cleanTerms[0], results: [] }
      }

      if (
        game === 'mtg' &&
        scanResult &&
        capturedCard &&
        best.results.length > 1
      ) {
        setStatus('Reading release details')
        const printingDetails = await recognizeMtgPrintingDetails(
          capturedCard,
          setStatus,
        )
        const detailedScanResult: ScanResult = {
          ...scanResult,
          rawText: [scanResult.rawText, printingDetails.rawText]
            .filter(Boolean)
            .join('\n'),
          setCodes: printingDetails.setCodes,
          collectorNumbers: printingDetails.collectorNumbers,
        }

        setScanResult(detailedScanResult)
        best.results = await rankMtgPrintingsBySetDetails(
          capturedCard,
          best.results,
          detailedScanResult,
          setStatus,
        )
      }

      if (reportedWrongPrintingId) {
        best.results = deprioritizeCandidate(best.results, reportedWrongPrintingId)
      }

      return { count: best.results.length, term: best.term, results: best.results }
    } catch {
      setStatus('Card lookup failed. Try manual search.')
      return { count: 0, term: cleanTerms[0], results: [] }
    } finally {
      setIsSearching(false)
    }
  }

  async function loadNextResultBatch() {
    const cleanTerm = (selectedTerm || query).trim()

    if (!cleanTerm) {
      setStatus('Search or scan a card first.')
      return
    }

    if (isSearching || isRefreshingResults) {
      return
    }

    const nextOffset = resultOffset + resultBatchSize

    setIsRefreshingResults(true)
    setStatus(`Loading more matches for "${cleanTerm}"`)

    try {
      const results = await searchCards(game, cleanTerm, {
        limit: resultBatchSize,
        offset: nextOffset,
      })
      const visibleKeys = new Set(candidates.map((card) => getImageKey(card)))
      const unseenResults = results.filter((card) => !visibleKeys.has(getImageKey(card)))

      if (!unseenResults.length) {
        setHasMoreResults(false)
        setStatus('No more matches found for this search.')
        return
      }

      setCandidates(unseenResults)
      setResultOffset(nextOffset)
      setHasMoreResults(results.length >= resultBatchSize)
      setStatus(`${unseenResults.length} more possible matches`)
    } catch {
      setStatus('Could not load more matches. Try again.')
    } finally {
      setIsRefreshingResults(false)
    }
  }

  async function startCamera() {
    if (isCameraOn) {
      stopCamera()
      return
    }

    if (!navigator.mediaDevices?.getUserMedia) {
      setStatus('Camera access is not available in this browser.')
      return
    }

    try {
      setScannerState('starting')
      setStatus('Starting camera')
      const stream = await openHighDetailCameraStream()

      await optimizeCameraTrack(stream.getVideoTracks()[0])
      cameraSessionRef.current += 1
      streamRef.current = stream
      lastAutoTermRef.current = ''
      setCapturedFrame('')
      setCandidates([])
      setScanResult(null)
      setSelectedTerm('')
      setResultOffset(0)
      setHasMoreResults(false)

      const video = videoRef.current

      if (!video) {
        stream.getTracks().forEach((track) => track.stop())
        setStatus('Camera preview is not ready yet.')
        setScannerState('idle')
        return
      }

      video.srcObject = stream
      await video.play()
      await waitForVideoReady(video)
      await prepareCameraFocus(stream.getVideoTracks()[0])

      setIsCameraOn(true)
      setScannerState('watching')
      setStatus('Hold one card steady in the frame, then tap Capture.')
    } catch {
      streamRef.current?.getTracks().forEach((track) => {
        track.stop()
      })
      streamRef.current = null
      setScannerState('idle')
      setStatus('Camera permission was denied or no camera was found.')
    }
  }

  function stopCamera(options: { silent?: boolean; keepScanActive?: boolean } = {}) {
    cameraSessionRef.current += 1
    if (!options.keepScanActive) {
      activeScanIdRef.current += 1
    }

    streamRef.current?.getTracks().forEach((track) => {
      track.stop()
    })
    streamRef.current = null

    if (videoRef.current) {
      videoRef.current.srcObject = null
    }

    setIsCameraOn(false)

    if (!options.keepScanActive) {
      setIsScanning(false)
      setScannerState('idle')
    }

    if (!options.silent) {
      setStatus('Camera stopped')
    }
  }

  async function captureCard() {
    const video = videoRef.current
    const canvas = canvasRef.current
    const scanId = activeScanIdRef.current + 1

    activeScanIdRef.current = scanId

    if (!video || !canvas || !video.videoWidth || !video.videoHeight) {
      setStatus('Camera is not ready yet.')
      return
    }

    setIsScanning(true)
    setScannerState('capturing')
    setStatus('Focusing and capturing the card.')

    try {
      const track = streamRef.current?.getVideoTracks()[0]
      await focusCameraForCapture(track)
      await drawCapturedCardToCanvas(video, canvas)
      const capturedImage = canvas.toDataURL('image/jpeg', 0.95)

      setCapturedFrame(capturedImage)
      setIsCameraOn(false)
      stopCamera({ silent: true, keepScanActive: true })
      setScannerState('reading')
      await readCapturedCard(canvas, scanId)
    } catch {
      setStatus('Scan failed. The image is kept; try search or start camera again.')
    } finally {
      if (activeScanIdRef.current === scanId) {
        setIsScanning(false)
        setScannerState('idle')
      }
    }
  }

  async function readCapturedCard(canvas: HTMLCanvasElement, scanId: number) {
    const ocrCanvas = createOcrCanvas(canvas)

    try {
      const result = await recognizeCardCanvas(ocrCanvas, setStatus, game)

      if (activeScanIdRef.current !== scanId) {
        return
      }

      setScanResult(result)

      {
        const scrollTopBeforeAutoSearch = window.scrollY
        const searchResult = result.terms.length
          ? await runAutoSearch(result.terms, result, ocrCanvas)
          : { count: 0, term: '', results: [] as CardCandidate[] }

        const normalizedTerm = normalizeName(searchResult.term)

        if (activeScanIdRef.current !== scanId) {
          return
        }

        setCandidates(searchResult.results)
        setSelectedTerm(searchResult.term)
        setResultOffset(0)
        setHasMoreResults(searchResult.results.length >= resultBatchSize)

        const matchedName = searchResult.results[0]?.name ?? searchResult.term
        setQuery(matchedName)

        if (searchResult.count > 0) {
          setStatus(`Matched "${matchedName}". Check the result, then save.`)
          return
        }

        window.requestAnimationFrame(() => {
          window.scrollTo({ top: scrollTopBeforeAutoSearch })
        })

        if (normalizedTerm === lastAutoTermRef.current) {
          setHasMoreResults(false)
          setStatus(`Still seeing "${searchResult.term}"`)
          return
        }

        lastAutoTermRef.current = normalizedTerm

        setStatus(
          searchResult.term
            ? `Read "${searchResult.term}" but did not trust the match.`
            : 'Could not read the card name. Type it or start the camera again.',
        )
      }
    } finally {
      ocrCanvas.width = 1
      ocrCanvas.height = 1
    }
  }

  function openSaveDeckDialog(
    candidate: CardCandidate,
    options: SaveDeckDialogOptions = {},
  ) {
    const gameDecks = decks.filter((deck) => deck.game === candidate.game)
    const firstDeckId = gameDecks.find((deck) => typeof deck.id === 'number')?.id
    const addToDeck = Boolean(options.addToDeck || options.createNewDeck)

    setSaveDeckDraft({
      candidate,
      addToDeck,
      collectionItemId: options.collectionItemId,
      deckId:
        options.createNewDeck || typeof firstDeckId !== 'number'
          ? createNewDeckValue
          : String(firstDeckId),
      newDeckName: '',
      quantity: '1',
      isSaving: false,
    })
  }

  function updateSaveDeckDraft(values: Partial<SaveDeckDraft>) {
    setSaveDeckDraft((current) => (current ? { ...current, ...values } : current))
  }

  async function confirmSaveDeckDraft() {
    if (!saveDeckDraft) {
      return
    }

    if (!saveDeckDraft.addToDeck) {
      await saveDraftWithoutDeck()
      return
    }

    const selectedDeckId = Number(saveDeckDraft.deckId)
    const quantity = Math.min(
      999,
      Math.max(1, Math.floor(Number(saveDeckDraft.quantity) || 1)),
    )
    const deckTarget = {
      deckId:
        saveDeckDraft.deckId === createNewDeckValue || !Number.isFinite(selectedDeckId)
          ? undefined
          : selectedDeckId,
      newDeckName: saveDeckDraft.newDeckName.trim(),
    }

    updateSaveDeckDraft({ isSaving: true })

    try {
      if (typeof saveDeckDraft.collectionItemId === 'number') {
        await addOwnedCollectionItemToDeck(
          saveDeckDraft.collectionItemId,
          saveDeckDraft.candidate,
          deckTarget,
          quantity,
        )
      } else {
        await saveCandidate(saveDeckDraft.candidate, deckTarget, quantity)
      }
      setSaveDeckDraft(null)
    } catch {
      setStatus('Save failed. Try again.')
      updateSaveDeckDraft({ isSaving: false })
    }
  }

  async function addOwnedCollectionItemToDeck(
    collectionItemId: number,
    candidate: CardCandidate,
    deckTarget: DeckSaveTarget,
    requestedQuantity: number,
  ) {
    const item = await db.collection.get(collectionItemId)
    if (!item) {
      throw new Error('The saved card is no longer available.')
    }

    const now = new Date().toISOString()
    const deck = await resolveDeckTarget(deckTarget, candidate.game, now)
    const currentDeckCards = await db.deckCards.toArray()
    const available = getAvailableQuantity(
      item.quantity,
      currentDeckCards,
      collectionItemId,
    )
    const quantity = Math.min(requestedQuantity, available)

    if (!quantity) {
      setSaveNotice(`${candidate.name} has no unassigned copies available.`)
      setStatus('No unassigned owned copies are available')
      return
    }

    await addCollectionItemToDeck(deck.id, collectionItemId, quantity, now)
    await db.decks.update(deck.id, { updatedAt: now })
    setSaveNotice(
      `${quantity} card${quantity === 1 ? '' : 's'} added to ${deck.name}: ${candidate.name}`,
    )
    setStatus(`Added ${candidate.name} to ${deck.name}`)
    await loadDeckData()
  }

  function openCoachCard(cardName: string, sourceId = '') {
    if (!coachDraft) {
      return
    }

    const card = collection.find(
      (item) => item.game === coachDraft.game && item.sourceId === sourceId,
    ) ?? collection.find(
      (item) =>
        item.game === coachDraft.game &&
        normalizeCardName(item.name) === normalizeCardName(cardName),
    )
    if (!card) {
      setCoachError(`${cardName} is no longer in this collection.`)
      return
    }

    setPreviewMenuOpen(false)
    setPreviewCard(card)
  }

  function renderCoachText(text: string, cardRefs: CoachCardRef[] = []) {
    if (!coachDraft) {
      return text
    }

    const refs = cardRefs.length
      ? cardRefs
      : collection
          .filter((item) => item.game === coachDraft.game)
          .map((item) => ({ name: item.name, sourceId: item.sourceId }))
    const names = uniqueStrings(
      refs
        .filter((ref) => text.toLowerCase().includes(ref.name.toLowerCase()))
        .map((ref) => ref.name),
    ).sort((left, right) => right.length - left.length)
    if (!names.length) {
      return text
    }

    const nameLookup = new Map(
      names.map((name) => [
        name.toLowerCase(),
        refs.find((ref) => ref.name.toLowerCase() === name.toLowerCase()),
      ]),
    )
    const parts = text.split(
      new RegExp(`(${names.map(escapeRegExp).join('|')})`, 'gi'),
    )

    return parts.map((part, index) => {
      const cardRef = nameLookup.get(part.toLowerCase())
      return cardRef ? (
        <button
          className="coach-inline-card-name"
          key={`${cardRef.sourceId}-${index}`}
          onClick={() => openCoachCard(cardRef.name, cardRef.sourceId)}
          type="button"
        >
          {part}
        </button>
      ) : (
        part
      )
    })
  }

  function getCoachCardRef(result: CoachResult, cardName: string) {
    return result.cardRefs.find(
      (ref) => normalizeCardName(ref.name) === normalizeCardName(cardName),
    )
  }

