  function renderGameTab(sectionGame: GameFilter) {
    const items = collection.filter((item) => item.game === sectionGame)
    const collectionQuery = collectionQueries[sectionGame]
    const visibleItems = items.filter((item) =>
      matchesCollectionSearch(item, collectionQuery),
    )
    const groups = groupCollection(visibleItems, collectionGroup, collectionSort)
    const quantity = items.reduce((total, item) => total + item.quantity, 0)
    const value = items.reduce(
      (total, item) => total + (item.priceUsd ?? 0) * item.quantity,
      0,
    )
    const gameLabel = getGameLabel(sectionGame)
    const getGroupKey = (label: string) => `${sectionGame}-${collectionGroup}-${label}`
    const isGroupOpen = (label: string) => collapsedGroups[getGroupKey(label)] === false
    const deckById = new Map(
      decks
        .filter((deck) => deck.game === sectionGame && typeof deck.id === 'number')
        .map((deck) => [deck.id as number, deck]),
    )
    const deckUsageByItemId = new Map<
      number,
      Array<{ deckId: number; deckName: string; quantity: number }>
    >()

    for (const entry of deckCards) {
      const deck = deckById.get(entry.deckId)

      if (!deck || entry.quantity < 1) {
        continue
      }

      const usages = deckUsageByItemId.get(entry.collectionItemId) ?? []
      usages.push({
        deckId: entry.deckId,
        deckName: deck.name,
        quantity: entry.quantity,
      })
      deckUsageByItemId.set(entry.collectionItemId, usages)
    }

    const renderCollectionItems = (groupItems: CollectionItem[]) => (
      <div className="collection-list">
        {groupItems.map((item) => {
          const deckUsage =
            typeof item.id === 'number' ? deckUsageByItemId.get(item.id) ?? [] : []
          const deckQuantity = deckUsage.reduce(
            (total, usage) => total + usage.quantity,
            0,
          )
          const deckUsageLabel =
            deckUsage.length === 1
              ? `Deck: ${deckUsage[0].deckName}`
              : `Decks: ${deckUsage[0]?.deckName} +${deckUsage.length - 1}`
          const itemMenuKey = `${item.game}-${item.id ?? item.sourceId}`

          return (
            <article className="collection-item" key={item.id}>
              <button
                aria-label={`Preview ${item.name}`}
                className="collection-preview-trigger"
                onClick={() => setPreviewCard(item)}
                title={`Preview ${item.name}`}
                type="button"
              >
                {renderCardImage(item)}
                <span className="item-main">
                  <h3>{item.name}</h3>
                  <span className="item-meta">
                    {item.setCode} #{item.collectorNumber} · {item.condition}
                  </span>
                  {item.notes && <span className="item-notes">{item.notes}</span>}
                  <span className="muted">
                    Checked {formatDate(item.lastPriceCheck)}
                  </span>
                </span>
              </button>
              <div className="item-price">
                <strong>{item.priceLabel}</strong>
                <span>{formatMoney((item.priceUsd ?? 0) * item.quantity)}</span>
                {deckQuantity > 0 && (
                  <details className="deck-usage">
                    <summary
                      aria-label={`${deckQuantity} ${item.name} ${
                        deckQuantity === 1 ? 'copy' : 'copies'
                      } assigned to decks`}
                    >
                      <FolderKanban aria-hidden="true" size={15} />
                      <span className="deck-usage-label">{deckUsageLabel}</span>
                    </summary>
                    <div className="deck-usage-popover">
                      {deckUsage.map((usage) => (
                        <div key={usage.deckId}>
                          <span>{usage.deckName}</span>
                          <strong>×{usage.quantity}</strong>
                        </div>
                      ))}
                    </div>
                  </details>
                )}
                <div
                  aria-label={`Collection quantity for ${item.name}`}
                  className="collection-quantity-stepper"
                >
                  <button
                    aria-label={`Decrease ${item.name} quantity`}
                    disabled={item.quantity <= 1}
                    onClick={() => void adjustCollectionItemQuantity(item.id, -1)}
                    title="Decrease quantity"
                    type="button"
                  >
                    <Minus size={17} />
                  </button>
                  <output aria-live="polite">{item.quantity}</output>
                  <button
                    aria-label={`Increase ${item.name} quantity`}
                    disabled={item.quantity >= 999}
                    onClick={() => void adjustCollectionItemQuantity(item.id, 1)}
                    title="Increase quantity"
                    type="button"
                  >
                    <Plus size={17} />
                  </button>
                </div>
                <div className="collection-item-menu">
                  <button
                    aria-expanded={openCollectionItemMenu === itemMenuKey}
                    aria-haspopup="menu"
                    aria-label={`${item.name} actions`}
                    onClick={() =>
                      setOpenCollectionItemMenu((current) =>
                        current === itemMenuKey ? null : itemMenuKey,
                      )
                    }
                    title="Card actions"
                    type="button"
                  >
                    <MoreVertical size={18} />
                  </button>
                  {openCollectionItemMenu === itemMenuKey && (
                    <div className="collection-item-menu-popover" role="menu">
                      <button
                        onClick={() => {
                          setOpenCollectionItemMenu(null)
                          openEditItem(item)
                        }}
                        role="menuitem"
                        type="button"
                      >
                        <Pencil size={17} />
                        Edit
                      </button>
                      <a
                        href={item.sourceUrl}
                        onClick={() => setOpenCollectionItemMenu(null)}
                        rel="noreferrer"
                        role="menuitem"
                        target="_blank"
                      >
                        <ExternalLink size={17} />
                        Open Webpage
                      </a>
                      <button
                        disabled={refreshingId === item.id}
                        onClick={() => {
                          setOpenCollectionItemMenu(null)
                          void refreshOne(item)
                        }}
                        role="menuitem"
                        type="button"
                      >
                        {refreshingId === item.id ? (
                          <Loader2 className="spin" size={17} />
                        ) : (
                          <RefreshCw size={17} />
                        )}
                        Refresh Price
                      </button>
                      <button
                        onClick={() => {
                          setOpenCollectionItemMenu(null)
                          void removeItem(item.id)
                        }}
                        role="menuitem"
                        type="button"
                      >
                        <Trash2 size={17} />
                        Delete
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </article>
          )
        })}
      </div>
    )

    return (
      <section className="workspace game-workspace">
        <section className="collection-panel">
          <div className="panel-heading collection-heading">
            <div>
              <h2>{gameLabel}</h2>
              <div className="collection-summary">
                <span className="muted">
                  {items.length} saved entries
                </span>
                <span className="collection-card-count">
                  {quantity} cards - {formatMoney(value)}
                </span>
              </div>
            </div>
            <div className="collection-heading-side">
              <button
                className="collection-deck-button"
                onClick={() => {
                  setDeckBuilderGame(sectionGame)
                  setSelectedDeckId(null)
                  setIsRenamingDeck(false)
                  setNewDeckNameDraft(null)
                  setOpenGameMenu(null)
                }}
                type="button"
              >
                <FolderKanban size={17} />
                Deck Builder
              </button>
              <div className="collection-heading-actions">
                <label className="collection-search">
                  <Search aria-hidden="true" size={17} />
                  <input
                    aria-label={`Search ${gameLabel} collection`}
                    onChange={(event) =>
                      setCollectionQueries((current) => ({
                        ...current,
                        [sectionGame]: event.target.value,
                      }))
                    }
                    onPointerDown={() => {
                      if (collectionQuery) {
                        setCollectionQueries((current) => ({
                          ...current,
                          [sectionGame]: '',
                        }))
                      }
                    }}
                    placeholder="Search cards"
                    type="search"
                    value={collectionQuery}
                  />
                </label>
                <button
                  className="collection-coach-button"
                  disabled={!items.length}
                  onClick={() => openLibraryCoach(sectionGame)}
                  type="button"
                >
                  <Sparkles size={17} />
                  Coach
                </button>
                <div className="game-menu">
                  <button
                    aria-expanded={openGameMenu === sectionGame}
                    aria-haspopup="menu"
                    aria-label={`${gameLabel} actions`}
                    onClick={() =>
                      setOpenGameMenu((current) =>
                        current === sectionGame ? null : sectionGame,
                      )
                    }
                    title={`${gameLabel} actions`}
                    type="button"
                  >
                    <MoreVertical size={18} />
                  </button>
                  {openGameMenu === sectionGame && (
                    <div className="game-menu-popover" role="menu">
                      <button
                        disabled={!items.length || refreshingId === 'all'}
                        onClick={() => {
                          setOpenGameMenu(null)
                          void refreshGame(sectionGame)
                        }}
                        role="menuitem"
                        type="button"
                      >
                        {refreshingId === 'all' ? (
                          <Loader2 className="spin" size={17} />
                        ) : (
                          <RefreshCw size={17} />
                        )}
                        Refresh Prices
                      </button>
                      <button
                        disabled={!items.length}
                        onClick={() => {
                          setOpenGameMenu(null)
                          exportGameCollection(sectionGame)
                        }}
                        role="menuitem"
                        type="button"
                      >
                        <Download size={17} />
                        Save / Export
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>

          <div className="collection-controls">
            <label>
              Group
              <select
                onChange={(event) =>
                  setCollectionGroup(event.target.value as CollectionGroup)
                }
                value={collectionGroup}
              >
                <option value="color">Color / Type</option>
                <option value="category">Card Type</option>
                <option value="set">Set</option>
                <option value="condition">Condition</option>
              </select>
            </label>
            <label>
              Sort
              <select
                onChange={(event) =>
                  setCollectionSort(event.target.value as CollectionSort)
                }
                value={collectionSort}
              >
                <option value="name">Name</option>
                <option value="value">Value</option>
                <option value="quantity">Quantity</option>
                <option value="newest">Newest</option>
              </select>
            </label>
          </div>

          {items.length === 0 ? (
            <div className="empty-state">
              <Database size={32} />
              <h3>No {gameLabel} cards saved yet</h3>
              <p>Scan or search a card, check the match, then tap save.</p>
            </div>
          ) : visibleItems.length === 0 ? (
            <div className="empty-state">
              <Search size={32} />
              <h3>No matching cards</h3>
              <p>Try another card name, set, color, type, or note.</p>
              <button
                onClick={() =>
                  setCollectionQueries((current) => ({
                    ...current,
                    [sectionGame]: '',
                  }))
                }
                type="button"
              >
                Clear Search
              </button>
            </div>
          ) : (
            <div className="grouped-collection">
              {groups.map((group) => (
                <section className="collection-group" key={group.label}>
                  <button
                    aria-expanded={isGroupOpen(group.label)}
                    className="group-heading"
                    onClick={() => toggleCollectionGroup(getGroupKey(group.label))}
                    type="button"
                  >
                    <span className="group-title">
                      {isGroupOpen(group.label) ? (
                        <ChevronUp size={18} />
                      ) : (
                        <ChevronDown size={18} />
                      )}
                      <strong>{group.label}</strong>
                    </span>
                    <span>
                      {formatDistinctCardCount(group.distinctCards)} ·{' '}
                      {formatMoney(group.value)}
                    </span>
                  </button>
                  {isGroupOpen(group.label) && (
                    sectionGame === 'mtg' &&
                    collectionGroup === 'color' &&
                    [
                      'White',
                      'Blue',
                      'Black',
                      'Red',
                      'Green',
                      'Multicolor',
                      'Colorless',
                      'Land',
                    ].includes(group.label) ? (
                      <div className="collection-subgroups">
                        {groupMtgColorSectionItems(group.label, group.items).map((subgroup) => {
                          const subgroupStateKey = `${group.label}/${subgroup.label}`
                          return (
                            <section className="collection-subgroup" key={subgroup.label}>
                              <button
                                aria-expanded={isGroupOpen(subgroupStateKey)}
                                className="group-heading subgroup-heading"
                                onClick={() =>
                                  toggleCollectionGroup(getGroupKey(subgroupStateKey))
                                }
                                type="button"
                              >
                                <span className="group-title">
                                  {isGroupOpen(subgroupStateKey) ? (
                                    <ChevronUp size={17} />
                                  ) : (
                                    <ChevronDown size={17} />
                                  )}
                                  <strong>{subgroup.label}</strong>
                                </span>
                                <span>
                                  {formatDistinctCardCount(subgroup.distinctCards)} ·{' '}
                                  {formatMoney(subgroup.value)}
                                </span>
                              </button>
                              {isGroupOpen(subgroupStateKey) &&
                                renderCollectionItems(subgroup.items)}
                            </section>
                          )
                        })}
                      </div>
                    ) : (
                      renderCollectionItems(group.items)
                    )
                  )}
                </section>
              ))}
            </div>
          )}
        </section>
      </section>
    )
  }

  function toggleCollectionGroup(groupKey: string) {
    setCollapsedGroups((current) => ({
      ...current,
      [groupKey]: current[groupKey] === false,
    }))
  }

  function renderSaveDeckDialog() {
    if (!saveDeckDraft) {
      return null
    }

    const candidate = saveDeckDraft.candidate
    const gameDecks = decks.filter((deck) => deck.game === candidate.game)
    const isCreatingDeck =
      saveDeckDraft.addToDeck &&
      (saveDeckDraft.deckId === createNewDeckValue || gameDecks.length === 0)
    const saveQuantity = Math.min(
      999,
      Math.max(1, Math.floor(Number(saveDeckDraft.quantity) || 1)),
    )

    return (
      <div
        aria-modal="true"
        className="card-preview-backdrop save-deck-backdrop"
        onClick={() => {
          if (!saveDeckDraft.isSaving) {
            setSaveDeckDraft(null)
          }
        }}
        role="dialog"
      >
        <section
          className="save-deck-popout"
          onClick={(event) => event.stopPropagation()}
        >
          <button
            aria-label="Close save options"
            className="preview-close"
            disabled={saveDeckDraft.isSaving}
            onClick={() => setSaveDeckDraft(null)}
            title="Close"
            type="button"
          >
            <X size={20} />
          </button>

          <div>
            <h2>
              {typeof saveDeckDraft.collectionItemId === 'number'
                ? 'Add to Deck'
                : 'Save Card'}
            </h2>
            <p className="muted">
              {candidate.name} · {getGameLabel(candidate.game)}
            </p>
          </div>

          <div className="save-quantity-row">
            <span>Quantity</span>
            <div className="save-quantity-stepper">
              <button
                aria-label="Decrease save quantity"
                disabled={saveDeckDraft.isSaving || saveQuantity <= 1}
                onClick={() =>
                  updateSaveDeckDraft({ quantity: String(saveQuantity - 1) })
                }
                title="Decrease quantity"
                type="button"
              >
                <Minus size={17} />
              </button>
              <output aria-live="polite">{saveQuantity}</output>
              <button
                aria-label="Increase save quantity"
                disabled={saveDeckDraft.isSaving || saveQuantity >= 999}
                onClick={() =>
                  updateSaveDeckDraft({ quantity: String(saveQuantity + 1) })
                }
                title="Increase quantity"
                type="button"
              >
                <Plus size={17} />
              </button>
            </div>
          </div>

          {typeof saveDeckDraft.collectionItemId !== 'number' && (
            <div className="save-choice">
              <button
                className={!saveDeckDraft.addToDeck ? 'active' : ''}
                disabled={saveDeckDraft.isSaving}
                onClick={() => void saveDraftWithoutDeck()}
                type="button"
              >
                {saveDeckDraft.isSaving && !saveDeckDraft.addToDeck ? (
                  <Loader2 className="spin" size={18} />
                ) : (
                  <Save size={18} />
                )}
                No, just save
              </button>
              <button
                className={saveDeckDraft.addToDeck ? 'active' : ''}
                disabled={saveDeckDraft.isSaving}
                onClick={() =>
                  updateSaveDeckDraft({
                    addToDeck: true,
                    deckId: gameDecks[0]?.id
                      ? String(gameDecks[0].id)
                      : createNewDeckValue,
                  })
                }
                type="button"
              >
                Yes, add to deck
              </button>
            </div>
          )}

          {saveDeckDraft.addToDeck && (
            <div className="deck-save-fields">
              <label>
                Deck
                <select
                  disabled={saveDeckDraft.isSaving}
                  onChange={(event) =>
                    updateSaveDeckDraft({ deckId: event.target.value })
                  }
                  value={
                    gameDecks.length === 0 ? createNewDeckValue : saveDeckDraft.deckId
                  }
                >
                  {gameDecks.map((deck) => (
                    <option key={deck.id} value={String(deck.id)}>
                      {deck.name}
                    </option>
                  ))}
                  <option value={createNewDeckValue}>Create new deck</option>
                </select>
              </label>

              {isCreatingDeck && (
                <label>
                  New deck name
                  <input
                    disabled={saveDeckDraft.isSaving}
                    onChange={(event) =>
                      updateSaveDeckDraft({ newDeckName: event.target.value })
                    }
                    placeholder={`${getGameLabel(candidate.game)} Deck`}
                    value={saveDeckDraft.newDeckName}
                  />
                </label>
              )}

            </div>
          )}

          {saveDeckDraft.addToDeck && (
            <div className="edit-actions">
              <button
                className="secondary"
                disabled={saveDeckDraft.isSaving}
                onClick={() => setSaveDeckDraft(null)}
                type="button"
              >
                Cancel
              </button>
              <button
                className="primary"
                disabled={saveDeckDraft.isSaving}
                onClick={() => void confirmSaveDeckDraft()}
                type="button"
              >
                {saveDeckDraft.isSaving ? (
                  <Loader2 className="spin" size={18} />
                ) : (
                  <Save size={18} />
                )}
                {isCreatingDeck ? 'Create Deck and Add' : 'Add to Deck'}
              </button>
            </div>
          )}
        </section>
      </div>
    )
  }

  function renderDeckBuilder(gameName: GameFilter) {
    const gameDecks = decks.filter((deck) => deck.game === gameName)
    const selectedDeck = gameDecks.find((deck) => deck.id === selectedDeckId)

    if (selectedDeck?.id) {
      const entries = deckCards
        .filter((entry) => entry.deckId === selectedDeck.id)
        .map((entry) => ({
          entry,
          item: collection.find((item) => item.id === entry.collectionItemId),
        }))
        .filter(
          (
            value,
          ): value is {
            entry: DeckCard
            item: CollectionItem
          } => Boolean(value.item),
        )
        .sort((left, right) => left.item.name.localeCompare(right.item.name))
      const totalCards = entries.reduce(
        (total, value) => total + value.entry.quantity,
        0,
      )
      const estimatedValue = entries.reduce(
        (total, value) =>
          total + (value.item.priceUsd ?? 0) * value.entry.quantity,
        0,
      )
      const deckGroups = groupDeckEditorEntries(
        entries,
        gameName,
        selectedDeck.commanderName,
      )
      const getDeckGroupKey = (label: string) =>
        `deck-${selectedDeck.id}-${label}`
      const isDeckGroupOpen = (label: string) =>
        collapsedGroups[getDeckGroupKey(label)] === false

    return (
      <div
        aria-modal="true"
        className="card-preview-backdrop"
          onClick={() => {
            setDeckBuilderGame(null)
            setSelectedDeckId(null)
            setIsRenamingDeck(false)
          }}
        role="dialog"
      >
        <section
            className="deck-popout deck-detail-popout"
          onClick={(event) => event.stopPropagation()}
        >
          <button
            aria-label="Close deck builder"
            className="preview-close"
              onClick={() => {
                setDeckBuilderGame(null)
                setSelectedDeckId(null)
                setIsRenamingDeck(false)
              }}
            title="Close"
            type="button"
          >
            <X size={20} />
          </button>

            <div className="deck-detail-heading">
              <button
                aria-label="Back to decks"
                className="deck-back-button"
                onClick={() => {
                  setSelectedDeckId(null)
                  setIsRenamingDeck(false)
                }}
                title="Back to decks"
                type="button"
              >
                <ChevronLeft size={20} />
              </button>
              <div>
                {isRenamingDeck ? (
                  <div className="deck-name-editor">
                    <input
                      aria-label="Deck name"
                      autoFocus
                      onChange={(event) => setDeckNameDraft(event.target.value)}
                      onKeyDown={(event) => {
                        if (event.key === 'Enter') {
                          void saveDeckName(selectedDeck)
                        }
                      }}
                      value={deckNameDraft}
                    />
                    <button
                      aria-label="Save deck name"
                      onClick={() => void saveDeckName(selectedDeck)}
                      title="Save deck name"
                      type="button"
                    >
                      <Save size={18} />
                    </button>
                  </div>
                ) : (
                  <div className="deck-title-row">
                    <h2>{selectedDeck.name}</h2>
                    <button
                      aria-label="Rename deck"
                      onClick={() => {
                        setDeckNameDraft(selectedDeck.name)
                        setIsRenamingDeck(true)
                      }}
                      title="Rename deck"
                      type="button"
                    >
                      <Pencil size={17} />
                    </button>
                    <button
                      aria-label={`Delete ${selectedDeck.name}`}
                      className="deck-delete-button"
                      onClick={() => setDeckDeleteDraft(selectedDeck)}
                      title="Delete deck"
                      type="button"
                    >
                      <Trash2 size={17} />
                    </button>
                  </div>
                )}
                <p className="muted">{getGameLabel(gameName)} deck</p>
              </div>
            </div>

            <div className="deck-stats">
              <span>
                <strong>{totalCards}</strong>
                Cards
              </span>
              <span>
                <strong>{entries.length}</strong>
                Unique
              </span>
              <span>
                <strong>{formatMoney(estimatedValue)}</strong>
                Est. value
              </span>
            </div>

            <button
              className="coach-launch-button"
              onClick={() => openCoach(selectedDeck)}
              type="button"
            >
              <Sparkles size={18} />
              Coach
            </button>

            {entries.length === 0 ? (
              <div className="mini-empty-state">
                <FolderKanban size={24} />
                <span>This deck is empty.</span>
              </div>
            ) : (
              <div className="deck-category-list">
                {deckGroups.map((group) => (
                  <section className="deck-category" key={group.label}>
                    <button
                      aria-expanded={isDeckGroupOpen(group.label)}
                      className="group-heading deck-category-heading"
                      onClick={() =>
                        toggleCollectionGroup(getDeckGroupKey(group.label))
                      }
                      type="button"
                    >
                      <span className="group-title">
                        {isDeckGroupOpen(group.label) ? (
                          <ChevronUp size={18} />
                        ) : (
                          <ChevronDown size={18} />
                        )}
                        <strong>{group.label}</strong>
                      </span>
                      <span>
                        {group.entries.length} different · {group.quantity}{' '}
                        {group.quantity === 1 ? 'card' : 'cards'}
                      </span>
                    </button>
                    {isDeckGroupOpen(group.label) && (
                      <div className="collection-list deck-card-list">
                        {group.entries.map(({ entry, item }) => (
                          <article
                            className="collection-item deck-card-item"
                            key={entry.id}
                          >
                    <button
                      aria-label={`Open ${item.name}`}
                      className="deck-card-image-button"
                      onClick={() => setPreviewCard(item)}
                      title={`Open ${item.name}`}
                      type="button"
                    >
                      {renderCardImage(item)}
                    </button>
                    <div className="item-main">
                      <h3>{item.name}</h3>
                      <p>
                        {item.setCode} #{item.collectorNumber}
                      </p>
                      <span className="muted">{item.category}</span>
                    </div>
                    <div className="item-price">
                      <strong>{item.priceLabel}</strong>
                      <span>
                        {formatMoney((item.priceUsd ?? 0) * entry.quantity)}
                      </span>
                      <div className="deck-card-actions">
                        <div
                          aria-label={`Deck quantity for ${item.name}`}
                          className="deck-quantity-stepper"
                        >
                          <button
                            aria-label={`Decrease ${item.name} quantity`}
                            disabled={entry.quantity <= 1}
                            onClick={() =>
                              void adjustDeckCardQuantity(entry.id, -1)
                            }
                            title="Decrease quantity"
                            type="button"
                          >
                            <Minus size={16} />
                          </button>
                          <output aria-live="polite">{entry.quantity}</output>
                          <button
                            aria-label={`Increase ${item.name} quantity`}
                            disabled={entry.quantity >= 999}
                            onClick={() =>
                              void adjustDeckCardQuantity(entry.id, 1)
                            }
                            title="Increase quantity"
                            type="button"
                          >
                            <Plus size={16} />
                          </button>
                        </div>
                        <div className="icon-actions">
                          <a
                            aria-label={`Open source for ${item.name}`}
                            href={item.sourceUrl}
                            rel="noreferrer"
                            target="_blank"
                            title="Open source"
                          >
                            <ExternalLink size={17} />
                          </a>
                          <button
                            onClick={() => void removeCardFromDeck(entry.id)}
                            title="Remove from deck"
                            type="button"
                          >
                            <Trash2 size={17} />
                          </button>
                        </div>
                      </div>
                    </div>
                          </article>
                        ))}
                      </div>
                    )}
                  </section>
                ))}
              </div>
            )}
          </section>
        </div>
      )
    }

    return (
      <div
        aria-modal="true"
        className="card-preview-backdrop"
        onClick={() => {
          setDeckBuilderGame(null)
          setSelectedDeckId(null)
          setNewDeckNameDraft(null)
        }}
        role="dialog"
      >
        <section
          className="deck-popout"
          onClick={(event) => event.stopPropagation()}
        >
          <button
            aria-label="Close deck builder"
            className="preview-close"
            onClick={() => {
              setDeckBuilderGame(null)
              setSelectedDeckId(null)
              setNewDeckNameDraft(null)
            }}
            title="Close"
            type="button"
          >
            <X size={20} />
          </button>
          <div className="deck-list-heading">
            <div>
              <h2>{getGameLabel(gameName)} Decks</h2>
              <p className="muted">Select a deck to view and edit its cards.</p>
            </div>
            <button
              aria-label="Add new deck"
              className="deck-add-button"
              onClick={() => setNewDeckNameDraft('')}
              title="Add new deck"
              type="button"
            >
              <Plus size={20} />
            </button>
          </div>

          {newDeckNameDraft !== null && (
            <form
              className="deck-create-row"
              onSubmit={(event) => {
                event.preventDefault()
                void createDeckFromBuilder(gameName)
              }}
            >
              <input
                aria-label="New deck name"
                autoFocus
                onChange={(event) => setNewDeckNameDraft(event.target.value)}
                placeholder={`${getGameLabel(gameName)} Deck`}
                value={newDeckNameDraft}
              />
              <button
                aria-label="Cancel new deck"
                className="secondary"
                onClick={() => setNewDeckNameDraft(null)}
                title="Cancel"
                type="button"
              >
                <X size={18} />
              </button>
              <button
                aria-label="Create deck"
                className="primary"
                title="Create deck"
                type="submit"
              >
                <Save size={18} />
              </button>
            </form>
          )}

          {gameDecks.length === 0 ? (
            <div className="mini-empty-state">
              <FolderKanban size={24} />
              <span>No {getGameLabel(gameName)} decks yet.</span>
            </div>
          ) : (
            <div className="deck-list">
              {gameDecks.map((deck) => {
                const cardsInDeck = deckCards
                  .filter((entry) => entry.deckId === deck.id)
                  .reduce((total, entry) => total + entry.quantity, 0)

                return (
                  <button
                    className="deck-row"
                    key={deck.id}
                    onClick={() => {
                      if (typeof deck.id === 'number') {
                        setSelectedDeckId(deck.id)
                        setDeckNameDraft(deck.name)
                      }
                    }}
                    type="button"
                  >
                    <div>
                      <h3>{deck.name}</h3>
                      <p className="muted">Updated {formatDate(deck.updatedAt)}</p>
                    </div>
                    <span className="deck-row-count">
                      <strong>{cardsInDeck}</strong>
                      cards
                      <ChevronRight size={18} />
                    </span>
                  </button>
                )
              })}
            </div>
          )}
        </section>
      </div>
    )
  }

  function renderDeckDeleteDialog() {
    if (!deckDeleteDraft || typeof deckDeleteDraft.id !== 'number') {
      return null
    }

    const assignedQuantity = deckCards
      .filter((entry) => entry.deckId === deckDeleteDraft.id)
      .reduce((total, entry) => total + entry.quantity, 0)

    return (
      <div
        aria-modal="true"
        className="card-preview-backdrop deck-delete-backdrop"
        onClick={() => setDeckDeleteDraft(null)}
        role="dialog"
      >
        <section
          className="save-deck-popout deck-delete-popout"
          onClick={(event) => event.stopPropagation()}
        >
          <button
            aria-label="Cancel deck deletion"
            className="preview-close"
            onClick={() => setDeckDeleteDraft(null)}
            title="Cancel"
            type="button"
          >
            <X size={20} />
          </button>
          <div className="deck-delete-heading">
            <Trash2 size={22} />
            <div>
              <h2>Delete {deckDeleteDraft.name}?</h2>
              <p className="muted">This cannot be undone.</p>
            </div>
          </div>
          <p>
            The deck and its {assignedQuantity} assigned{' '}
            {assignedQuantity === 1 ? 'card' : 'cards'} will be removed. Your
            collection cards will remain saved and become available to other
            decks.
          </p>
          <div className="deck-delete-actions">
            <button
              className="secondary"
              onClick={() => setDeckDeleteDraft(null)}
              type="button"
            >
              Cancel
            </button>
            <button
              className="danger-action"
              onClick={() => void deleteDeck(deckDeleteDraft)}
              type="button"
            >
              <Trash2 size={18} />
              Delete Deck
            </button>
          </div>
        </section>
      </div>
    )
  }

  function renderCoachDialog() {
    if (!coachDraft) {
      return null
    }

    const deck = decks.find((item) => item.id === coachDraft.deckId)
    const formatOptions = getCoachFormats(coachDraft.game)
    const deterministic = coachResult?.deterministic
    const strengths = uniqueStrings([
      ...(deterministic?.strengths ?? []),
      ...(coachResult?.strengths ?? []),
    ])
    const concerns = uniqueStrings([
      ...(deterministic?.concerns ?? []),
      ...(coachResult?.concerns ?? []),
    ])
    const quickPrompts = getCoachQuickPrompts(
      coachDraft.game,
      coachDraft.scope,
    )
    const comboColorOptions = getCoachComboColorOptions(coachDraft.game)
    const buildColorOptions = getCoachBuildColorOptions(coachDraft.game)

    return (
      <div
        aria-modal="true"
        className="card-preview-backdrop coach-backdrop"
        onClick={() => {
          if (!isCoachLoading) {
            setCoachDraft(null)
            setCoachComboRefinement(null)
            setCoachBuildRefinement(null)
          }
        }}
        role="dialog"
      >
        <section
          className="coach-popout"
          onClick={(event) => event.stopPropagation()}
        >
          <button
            aria-label="Close Coach"
            className="preview-close"
            disabled={isCoachLoading}
            onClick={() => {
              setCoachDraft(null)
              setCoachComboRefinement(null)
              setCoachBuildRefinement(null)
            }}
            title="Close"
            type="button"
          >
            <X size={20} />
          </button>

          <header className="coach-heading">
            <div className="coach-mark">
              <Sparkles size={22} />
            </div>
            <div>
              <h2>Coach</h2>
              <p className="muted">
                {deck?.name ?? `${getGameLabel(coachDraft.game)} Library`}
              </p>
            </div>
          </header>

          {coachDraft.scope === 'deck' && (
            <div className="coach-format-bar">
              <label>
                Deck format
                <select
                  disabled={isCoachLoading}
                  onChange={(event) =>
                    updateCoachDraft({
                      format: event.target.value,
                      commanderName:
                        event.target.value === 'commander'
                          ? coachDraft.commanderName
                          : '',
                    })
                  }
                  value={coachDraft.format}
                >
                  {formatOptions.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </label>

              {coachDraft.game === 'mtg' &&
                coachDraft.format === 'commander' && (
                  <label>
                    Commander
                    <input
                      disabled={isCoachLoading}
                      onChange={(event) =>
                        updateCoachDraft({ commanderName: event.target.value })
                      }
                      placeholder="Card name"
                      value={coachDraft.commanderName}
                    />
                  </label>
                )}
            </div>
          )}

          <div className="coach-chat" aria-live="polite">
            <div className="coach-message assistant">
              <div className="coach-message-mark">
                <Sparkles size={16} />
              </div>
              <div className="coach-message-body">
                <strong>What do you want help with?</strong>
                <p>
                  I know your {getGameLabel(coachDraft.game)}{' '}
                  {coachDraft.scope === 'deck' ? 'deck and collection' : 'collection'}.
                  Ask about cards you own, abilities, attacks, mana, or combos.
                </p>
              </div>
            </div>

            {coachMessages.map((message) => (
              <div
                className={`coach-message ${message.role}`}
                key={message.id}
              >
                {message.role === 'assistant' && (
                  <div className="coach-message-mark">
                    <Sparkles size={16} />
                  </div>
                )}
                <div className="coach-message-body">
                  <p>
                    {message.role === 'assistant'
                      ? renderCoachText(message.text, message.result?.cardRefs)
                      : message.text}
                  </p>

                  {message.result?.mode === 'build' &&
                    message.result.ownedRecommendations.length > 0 && (
                      <div className="coach-save-deck-action">
                        <button
                          className="coach-save-deck-button"
                          disabled={
                            Boolean(savingCoachDeckMessageId) ||
                            Boolean(savedCoachDeckNames[message.id])
                          }
                          onClick={() => void saveCoachGeneratedDeck(message)}
                          title="Save this generated deck"
                          type="button"
                        >
                          {savingCoachDeckMessageId === message.id ? (
                            <Loader2 className="spin" size={17} />
                          ) : (
                            <Plus size={17} />
                          )}
                          {savedCoachDeckNames[message.id]
                            ? `Saved as ${savedCoachDeckNames[message.id]}`
                            : 'Save as New Deck'}
                        </button>
                      </div>
                    )}

                  {message.result?.synergies.length ? (
                    <div className="coach-answer-cards">
                      {message.result.synergies.map((synergy, index) => (
                        <article key={`${message.id}-synergy-${index}`}>
                          {synergy.tier && (
                            <span className="coach-synergy-tier">{synergy.tier}</span>
                          )}
                          <div className="coach-card-name-row">
                            {synergy.cards.map((cardName, cardIndex) => {
                              const cardRef = getCoachCardRef(message.result!, cardName)
                              return (
                                <span key={`${message.id}-${cardName}`}>
                                  {cardIndex > 0 && <i>+</i>}
                                  <button
                                    onClick={() =>
                                      openCoachCard(cardName, cardRef?.sourceId)
                                    }
                                    type="button"
                                  >
                                    {cardName}
                                  </button>
                                </span>
                              )
                            })}
                          </div>
                          <p>
                            {renderCoachText(
                              synergy.explanation,
                              message.result!.cardRefs,
                            )}
                          </p>
                        </article>
                      ))}
                    </div>
                  ) : null}

                  {message.result?.ownedRecommendations.length ? (
                    <div className="coach-answer-cards">
                      {message.result.ownedRecommendations.map(
                        (recommendation, index) =>
                          renderCoachOwnedRecommendation(
                            message,
                            recommendation,
                            index,
                          ),
                      )}
                    </div>
                  ) : null}

                  {message.result &&
                    message.result.synergies.length === 0 &&
                    message.result.ownedRecommendations.length === 0 &&
                    (message.result.strengths.length > 0 ||
                      message.result.concerns.length > 0) && (
                      <ul className="coach-answer-points">
                        {[
                          ...message.result.strengths,
                          ...message.result.concerns,
                        ].map((item) => (
                          <li key={`${message.id}-${item}`}>
                            {renderCoachText(item, message.result!.cardRefs)}
                          </li>
                        ))}
                      </ul>
                    )}

                  {message.result && (
                    <details className="coach-answer-details">
                      <summary>Answer details</summary>
                      <p>
                        {message.result.mode === 'build' ? (
                          <>
                            {countCoachAdditions(message.result)} nonland cards
                            selected. Coach searched{' '}
                            {message.result.analysisScope.collectionCardsMatched ??
                              message.result.analysisScope.collectionCardsHydrated}{' '}
                            matching owned cards and closely checked{' '}
                            {message.result.analysisScope.collectionCardsHydrated}.
                          </>
                        ) : (
                          <>
                            Coach searched{' '}
                            {message.result.analysisScope.collectionCardsMatched ??
                              message.result.analysisScope.collectionCardsHydrated}{' '}
                            matching owned cards and closely checked{' '}
                            {message.result.analysisScope.collectionCardsHydrated ||
                              message.result.analysisScope.collectionCardsModeled}.
                          </>
                        )}
                      </p>
                      {message.result.deterministic.legalityIssues.length > 0 && (
                        <ul>
                          {message.result.deterministic.legalityIssues.map(
                            (issue, index) => (
                              <li key={`${message.id}-issue-${index}`}>
                                <b>{issue.card}:</b> {issue.issue}
                              </li>
                            ),
                          )}
                        </ul>
                      )}
                    </details>
                  )}
                </div>
              </div>
            ))}

            {isCoachLoading && (
              <div className="coach-message assistant thinking">
                <div className="coach-message-mark">
                  <Loader2 className="spin" size={16} />
                </div>
                <div className="coach-message-body">
                  <p>Checking your cards and their exact rules...</p>
                </div>
              </div>
            )}
            {isCoachDeckBuildRunning && (
              <div className="coach-build-wait coach-build-wait-chat" role="status">
                <TriangleAlert aria-hidden="true" size={18} />
                <span>
                  Building a full deck takes longer. Coach is checking your collection.
                </span>
              </div>
            )}
            <div ref={coachChatEndRef} />
          </div>

          {coachComboRefinement ? (
            <section className="coach-combo-refinement">
              <header>
                <div>
                  <strong>Useful combo filters</strong>
                  <span>Only cards you own will be checked.</span>
                </div>
                <button
                  aria-label="Close combo filters"
                  onClick={() => setCoachComboRefinement(null)}
                  title="Close filters"
                  type="button"
                >
                  <X size={17} />
                </button>
              </header>

              <fieldset>
                <legend>
                  {coachDraft.game === 'pokemon' ? 'Pokemon types' : 'Colors'}
                </legend>
                <div className="coach-filter-chips">
                  <button
                    className={
                      coachComboRefinement.colors.length === 0 ? 'active' : ''
                    }
                    onClick={() =>
                      setCoachComboRefinement((current) =>
                        current ? { ...current, colors: [] } : current,
                      )
                    }
                    type="button"
                  >
                    Any
                  </button>
                  {comboColorOptions.map((option) => (
                    <button
                      className={
                        coachComboRefinement.colors.includes(option.value)
                          ? 'active'
                          : ''
                      }
                      key={option.value}
                      onClick={() => toggleCoachComboColor(option.value)}
                      type="button"
                    >
                      {option.label}
                    </button>
                  ))}
                </div>
              </fieldset>

              <fieldset>
                <legend>Combo type</legend>
                <div className="coach-filter-chips">
                  {getCoachComboKinds().map((option) => (
                    <button
                      className={
                        coachComboRefinement.kind === option.value
                          ? 'active'
                          : ''
                      }
                      key={option.value}
                      onClick={() =>
                        setCoachComboRefinement((current) =>
                          current ? { ...current, kind: option.value } : current,
                        )
                      }
                      type="button"
                    >
                      {option.label}
                    </button>
                  ))}
                </div>
              </fieldset>

              {coachDraft.scope === 'deck' && (
                <fieldset>
                  <legend>Search area</legend>
                  <div className="coach-filter-chips">
                    {[
                      { label: 'This deck', value: 'deck' as const },
                      { label: 'Whole collection', value: 'collection' as const },
                    ].map((option) => (
                      <button
                        className={
                          coachComboRefinement.area === option.value
                            ? 'active'
                            : ''
                        }
                        key={option.value}
                        onClick={() =>
                          setCoachComboRefinement((current) =>
                            current ? { ...current, area: option.value } : current,
                          )
                        }
                        type="button"
                      >
                        {option.label}
                      </button>
                    ))}
                  </div>
                </fieldset>
              )}

              <div className="coach-filter-actions">
                <button
                  disabled={isCoachLoading}
                  onClick={() => askCoachForRefinedCombos(true)}
                  type="button"
                >
                  Skip filters
                </button>
                <button
                  className="primary"
                  disabled={isCoachLoading}
                  onClick={() => askCoachForRefinedCombos()}
                  type="button"
                >
                  <Sparkles size={17} />
                  Ask Coach
                </button>
              </div>
            </section>
          ) : coachBuildRefinement ? (
            <section className="coach-combo-refinement">
              <header>
                <div>
                  <strong>Deck build options</strong>
                  <span>Coach will build only from cards you own.</span>
                </div>
                <button
                  aria-label="Close deck build options"
                  onClick={() => setCoachBuildRefinement(null)}
                  title="Close options"
                  type="button"
                >
                  <X size={17} />
                </button>
              </header>

              <fieldset>
                <legend>
                  {coachDraft.game === 'pokemon' ? 'Pokemon types' : 'Colors'}
                </legend>
                <div className="coach-filter-chips">
                  <button
                    className={
                      coachBuildRefinement.colors.length === 0 ? 'active' : ''
                    }
                    onClick={() => {
                      setCommanderSuggestions([])
                      setCoachBuildRefinement((current) =>
                        current ? { ...current, colors: [] } : current,
                      )
                    }}
                    type="button"
                  >
                    Any
                  </button>
                  {buildColorOptions.map((option) => (
                    <button
                      className={
                        coachBuildRefinement.colors.includes(option.value)
                          ? 'active'
                          : ''
                      }
                      key={option.value}
                      onClick={() => toggleCoachBuildColor(option.value)}
                      type="button"
                    >
                      {option.label}
                    </button>
                  ))}
                </div>
              </fieldset>

              <fieldset>
                <legend>Deck style</legend>
                <div className="coach-filter-chips">
                  {getCoachBuildStyles(coachDraft.game).map((option) => (
                    <button
                      className={
                        coachBuildRefinement.style === option.value ? 'active' : ''
                      }
                      key={option.value}
                      onClick={() => {
                        setCommanderSuggestions([])
                        setCoachBuildRefinement((current) =>
                          current ? { ...current, style: option.value } : current,
                        )
                      }}
                      type="button"
                    >
                      {option.label}
                    </button>
                  ))}
                </div>
              </fieldset>

              <fieldset>
                <legend>Deck format</legend>
                <div className="coach-filter-chips">
                  {formatOptions.map((option) => (
                    <button
                      className={coachDraft.format === option.value ? 'active' : ''}
                      key={option.value}
                      onClick={() => {
                        setCommanderSuggestions([])
                        updateCoachDraft({
                          format: option.value,
                          commanderName:
                            option.value === 'commander'
                              ? coachDraft.commanderName
                              : '',
                        })
                      }}
                      type="button"
                    >
                      {option.label}
                    </button>
                  ))}
                </div>
                {coachDraft.game === 'mtg' &&
                  coachDraft.format === 'commander' && (
                    <div className="coach-build-commander">
                      <div className="coach-commander-label-row">
                        <span>Commander card</span>
                        <button
                          disabled={isCoachLoading || isSuggestingCommander}
                          onClick={() => void suggestCoachCommander()}
                          type="button"
                        >
                          {isSuggestingCommander ? (
                            <Loader2 className="spin" size={15} />
                          ) : (
                            <Sparkles size={15} />
                          )}
                          Suggest a Commander
                        </button>
                      </div>
                      <input
                        disabled={isCoachLoading}
                        onChange={(event) => {
                          setCommanderSuggestions([])
                          updateCoachDraft({ commanderName: event.target.value })
                        }}
                        placeholder="Card name"
                        value={coachDraft.commanderName}
                      />
                      {commanderSuggestions.length > 0 && (
                        <div className="coach-commander-suggestions">
                          {commanderSuggestions.map((suggestion) => {
                            const card = collection.find(
                              (item) => item.sourceId === suggestion.sourceId,
                            )
                            return (
                              <article key={suggestion.sourceId}>
                                <button
                                  className="coach-commander-preview"
                                  onClick={() =>
                                    openCoachCard(suggestion.name, suggestion.sourceId)
                                  }
                                  title={`View ${suggestion.name}`}
                                  type="button"
                                >
                                  {card?.imageUrl && (
                                    <img alt="" src={card.imageUrl} />
                                  )}
                                  <span>
                                    <strong>{suggestion.name}</strong>
                                    <small>{suggestion.reason}</small>
                                  </span>
                                </button>
                                <button
                                  className="coach-use-commander"
                                  onClick={() =>
                                    updateCoachDraft({ commanderName: suggestion.name })
                                  }
                                  type="button"
                                >
                                  <Check size={15} />
                                  Use Commander
                                </button>
                              </article>
                            )
                          })}
                        </div>
                      )}
                    </div>
                  )}
              </fieldset>

              <div className="coach-filter-actions">
                <button
                  disabled={isCoachLoading}
                  onClick={() => askCoachForRefinedBuild(true)}
                  type="button"
                >
                  Skip options
                </button>
                <button
                  className="primary"
                  disabled={isCoachLoading}
                  onClick={() => askCoachForRefinedBuild()}
                  type="button"
                >
                  <Sparkles size={17} />
                  Build Deck
                </button>
              </div>
            </section>
          ) : (
            <section className="coach-quick-section">
              <button
                aria-expanded={areCoachPromptsOpen}
                className="coach-quick-toggle"
                disabled={isCoachLoading}
                onClick={() => setAreCoachPromptsOpen((current) => !current)}
                type="button"
              >
                <span>Common questions</span>
                <ChevronDown
                  className={areCoachPromptsOpen ? 'is-open' : ''}
                  size={19}
                />
              </button>
              {areCoachPromptsOpen && (
                <div className="coach-quick-prompts">
                  {quickPrompts.map((prompt) => (
                    <button
                      disabled={isCoachLoading}
                      key={prompt.label}
                      onClick={() => selectCoachQuickPrompt(prompt)}
                      type="button"
                    >
                      {prompt.label}
                    </button>
                  ))}
                </div>
              )}
            </section>
          )}

          <form
            className="coach-composer"
            onSubmit={(event) => {
              event.preventDefault()
              void runCoach()
            }}
          >
            <textarea
              aria-label="Ask Coach"
              disabled={isCoachLoading}
              onChange={(event) => {
                setCoachQuestion(event.target.value)
                updateCoachDraft({ goal: event.target.value })
              }}
              onKeyDown={(event) => {
                if (event.key === 'Enter' && !event.shiftKey) {
                  event.preventDefault()
                  void runCoach()
                }
              }}
              placeholder="Ask Coach about cards you own..."
              rows={2}
              value={coachQuestion}
            />
            <button
              aria-label="Send question"
              disabled={isCoachLoading || !coachQuestion.trim()}
              title="Send"
              type="submit"
            >
              {isCoachLoading ? (
                <Loader2 className="spin" size={19} />
              ) : (
                <Send size={19} />
              )}
            </button>
          </form>

          {coachError && (
            <div className="coach-alert error" role="alert">
              <TriangleAlert size={18} />
              <span>{coachError}</span>
            </div>
          )}

          {coachResult && !isCoachLoading && (
            <details className="coach-full-analysis">
              <summary>Full deck analysis</summary>
              <div className="coach-results">
                <div className="coach-result-heading">
                  <div>
                    <span
                      className={`coach-status ${coachResult.modelStatus}`}
                    >
                      {coachResult.modelStatus === 'ready'
                        ? 'Coach ready'
                        : coachResult.modelStatus === 'partial'
                          ? 'Coach checked'
                        : coachResult.modelStatus === 'busy'
                          ? 'Checks only'
                          : 'Model offline'}
                    </span>
                    <h3>{renderCoachText(coachResult.summary, coachResult.cardRefs)}</h3>
                  </div>
                </div>

                {deterministic && (
                  <div className="coach-metrics">
                    {Object.entries(deterministic.metrics).map(([key, value]) => (
                      <span key={key}>
                        <strong>{value}</strong>
                        {formatMetricLabel(key)}
                      </span>
                    ))}
                  </div>
                )}

                {deterministic?.legalityIssues.length ? (
                  <section className="coach-section coach-legality">
                    <h3>
                      <TriangleAlert size={18} />
                      Deck Checks
                    </h3>
                    <div className="coach-list">
                      {deterministic.legalityIssues.map((issue, index) => (
                        <article key={`${issue.card}-${index}`}>
                          <strong>
                            {renderCoachText(issue.card, coachResult.cardRefs)}
                          </strong>
                          <p>{issue.issue}</p>
                        </article>
                      ))}
                    </div>
                  </section>
                ) : deterministic && coachDraft.scope === 'deck' ? (
                  <div className="coach-alert success">
                    <Check size={18} />
                    <span>Deck checks passed.</span>
                  </div>
                ) : null}

                {(strengths.length > 0 || concerns.length > 0) && (
                  <div className="coach-summary-grid">
                    {strengths.length > 0 && (
                      <section className="coach-section">
                        <h3>Working Well</h3>
                        <ul>
                          {strengths.map((item) => (
                            <li key={item}>
                              {renderCoachText(item, coachResult.cardRefs)}
                            </li>
                          ))}
                        </ul>
                      </section>
                    )}
                    {concerns.length > 0 && (
                      <section className="coach-section">
                        <h3>Needs Attention</h3>
                        <ul>
                          {concerns.map((item) => (
                            <li key={item}>
                              {renderCoachText(item, coachResult.cardRefs)}
                            </li>
                          ))}
                        </ul>
                      </section>
                    )}
                  </div>
                )}

                {coachResult.warnings.length > 0 && (
                  <details className="coach-notes">
                    <summary>Analysis notes</summary>
                    <ul>
                      {coachResult.warnings.map((warning) => (
                        <li key={warning}>{warning}</li>
                      ))}
                    </ul>
                  </details>
                )}
              </div>
            </details>
          )}
        </section>
      </div>
    )
  }

