function getCenteredCardCrop(videoWidth: number, videoHeight: number) {
  const cardAspect = 2.5 / 3.5
  let height = videoHeight
  let width = Math.round(height * cardAspect)

  if (width > videoWidth) {
    width = videoWidth
    height = Math.round(width / cardAspect)
  }

  return {
    x: Math.max(0, Math.round((videoWidth - width) / 2)),
    y: Math.max(0, Math.round((videoHeight - height) / 2)),
    width,
    height,
  }
}

async function drawCapturedCardToCanvas(
  video: HTMLVideoElement,
  canvas: HTMLCanvasElement,
) {
  const context = canvas.getContext('2d')

  if (!context) {
    throw new Error('Could not read the camera frame.')
  }

  const crop = getCenteredCardCrop(video.videoWidth, video.videoHeight)
  const maximumLongEdge = 2401
  const scale = Math.min(1, maximumLongEdge / Math.max(crop.width, crop.height))
  const outputWidth = Math.max(1, Math.round(crop.width * scale))
  const outputHeight = Math.max(1, Math.round(crop.height * scale))

  canvas.width = outputWidth
  canvas.height = outputHeight
  context.imageSmoothingEnabled = true
  context.imageSmoothingQuality = 'high'
  context.drawImage(
    video,
    crop.x,
    crop.y,
    crop.width,
    crop.height,
    0,
    0,
    outputWidth,
    outputHeight,
  )
}

function createOcrCanvas(source: HTMLCanvasElement) {
  const maximumLongEdge = 1401
  const scale = Math.min(1, maximumLongEdge / Math.max(source.width, source.height))
  const canvas = document.createElement('canvas')
  const context = canvas.getContext('2d')

  if (!context) {
    throw new Error('Could not prepare the card image for reading.')
  }

  canvas.width = Math.max(1, Math.round(source.width * scale))
  canvas.height = Math.max(1, Math.round(source.height * scale))
  context.imageSmoothingEnabled = true
  context.imageSmoothingQuality = 'high'
  context.drawImage(source, 0, 0, canvas.width, canvas.height)
  return canvas
}

async function openHighDetailCameraStream(): Promise<MediaStream> {
  let stream = await requestHighDetailCameraStream()
  let preferredCamera: MediaDeviceInfo | undefined

  try {
    preferredCamera = await findPrimaryRearCamera()
  } catch {
    // Keep the working rear stream when Android does not expose camera labels.
  }

  const activeDeviceId = stream.getVideoTracks()[0]?.getSettings().deviceId

  if (preferredCamera?.deviceId && preferredCamera.deviceId !== activeDeviceId) {
    stream.getTracks().forEach((track) => track.stop())

    try {
      stream = await requestHighDetailCameraStream(preferredCamera.deviceId)
    } catch {
      stream = await requestHighDetailCameraStream()
    }
  }

  return stream
}

async function requestHighDetailCameraStream(deviceId?: string): Promise<MediaStream> {
  const cameraSelection = deviceId
    ? { deviceId: { exact: deviceId } }
    : { facingMode: { ideal: 'environment' } }
  const videoConstraints: MediaTrackConstraints & {
    resizeMode?: { ideal: string }
  } = {
    ...cameraSelection,
    width: { min: 1280, ideal: 3840 },
    height: { min: 720, ideal: 2160 },
    frameRate: { ideal: 24, max: 30 },
    resizeMode: { ideal: 'none' },
  }
  const highDetailConstraints: MediaStreamConstraints = {
    video: videoConstraints,
    audio: false,
  }

  try {
    return await navigator.mediaDevices.getUserMedia(highDetailConstraints)
  } catch (error) {
    if (!(error instanceof DOMException) || error.name !== 'OverconstrainedError') {
      throw error
    }

    return navigator.mediaDevices.getUserMedia({
      video: {
        ...cameraSelection,
        width: { ideal: 3840 },
        height: { ideal: 2160 },
      },
      audio: false,
    })
  }
}

async function findPrimaryRearCamera(): Promise<MediaDeviceInfo | undefined> {
  const devices = await navigator.mediaDevices.enumerateDevices()
  const rearCameras = devices.filter((device) => {
    if (device.kind !== 'videoinput') {
      return false
    }

    const label = device.label.toLowerCase()
    return (
      (label.includes('back') || label.includes('rear') || label.includes('environment')) &&
      !label.includes('front')
    )
  })

  return rearCameras.sort(
    (left, right) => scoreRearCamera(right.label) - scoreRearCamera(left.label),
  )[0]
}

function scoreRearCamera(label: string) {
  const normalized = label.toLowerCase()
  let score = 0

  if (normalized.includes('main') || normalized.includes('primary')) {
    score += 101
  }
  if (normalized.includes('back') || normalized.includes('rear')) {
    score += 51
  }
  if (/\bcamera2?\s*0\b/.test(normalized)) {
    score += 31
  }
  if (
    normalized.includes('ultra') ||
    normalized.includes('macro') ||
    normalized.includes('tele') ||
    normalized.includes('depth')
  ) {
    score -= 201
  }

  return score
}

async function optimizeCameraTrack(track: MediaStreamTrack | undefined) {
  if (!track) {
    return
  }

  track.contentHint = 'detail'

  const capabilities = track.getCapabilities() as MediaTrackCapabilities & {
    exposureMode?: string[]
    focusMode?: string[]
    resizeMode?: string[]
    sharpness?: { max: number; min: number; step?: number }
    whiteBalanceMode?: string[]
  }
  const maximumWidth = Math.min(capabilities.width?.max ?? 3840, 3840)
  const maximumHeight = Math.min(capabilities.height?.max ?? 2160, 2160)
  const constraints: MediaTrackConstraints & { resizeMode?: { ideal: string } } = {
    width: {
      min: Math.min(maximumWidth, 1280),
      ideal: maximumWidth,
    },
    height: {
      min: Math.min(maximumHeight, 720),
      ideal: maximumHeight,
    },
    frameRate: { ideal: Math.min(capabilities.frameRate?.max ?? 24, 24), max: 30 },
  }

  if (capabilities.resizeMode?.includes('none')) {
    constraints.resizeMode = { ideal: 'none' }
  }

  try {
    await track.applyConstraints(constraints)
  } catch {
    // Keep the initial high-resolution constraints when this combination fails.
  }

  if (capabilities.focusMode?.includes('continuous')) {
    await applyOptionalCameraConstraint(track, { focusMode: 'continuous' })
  }
  if (capabilities.exposureMode?.includes('continuous')) {
    await applyOptionalCameraConstraint(track, { exposureMode: 'continuous' })
  }
  if (capabilities.whiteBalanceMode?.includes('continuous')) {
    await applyOptionalCameraConstraint(track, { whiteBalanceMode: 'continuous' })
  }
  if (
    capabilities.sharpness &&
    Number.isFinite(capabilities.sharpness.min) &&
    Number.isFinite(capabilities.sharpness.max) &&
    capabilities.sharpness.max > capabilities.sharpness.min
  ) {
    const sharpness =
      capabilities.sharpness.min +
      (capabilities.sharpness.max - capabilities.sharpness.min) * 0.85
    await applyOptionalCameraConstraint(track, { sharpness })
  }
}

async function prepareCameraFocus(track: MediaStreamTrack | undefined) {
  if (!track) {
    return
  }

  const capabilities = track.getCapabilities() as MediaTrackCapabilities & {
    focusMode?: string[]
  }

  if (capabilities.focusMode?.includes('continuous')) {
    await applyOptionalCameraConstraint(track, { focusMode: 'continuous' })
  }

  await waitForCameraFocus(1001)
}

async function focusCameraForCapture(track: MediaStreamTrack | undefined) {
  if (!track) {
    return
  }

  const capabilities = track.getCapabilities() as MediaTrackCapabilities & {
    focusMode?: string[]
  }

  if (capabilities.focusMode?.includes('single-shot')) {
    await applyOptionalCameraConstraint(track, { focusMode: 'single-shot' })
    await waitForCameraFocus(1001)
    return
  }

  if (capabilities.focusMode?.includes('continuous')) {
    await applyOptionalCameraConstraint(track, { focusMode: 'continuous' })
    await waitForCameraFocus(751)
    return
  }

  // Android WebView may omit focus capabilities while its camera still autofocuses.
  await waitForCameraFocus(1001)
}

async function applyOptionalCameraConstraint(
  track: MediaStreamTrack,
  constraint: Record<string, string | number>,
) {
  try {
    const currentConstraints = track.getConstraints()
    const currentAdvanced =
      (
        currentConstraints as MediaTrackConstraints & {
          advanced?: MediaTrackConstraintSet[]
        }
      ).advanced ?? []
    const constraintKeys = Object.keys(constraint)
    const preservedAdvanced = currentAdvanced.filter((advancedConstraint) =>
      constraintKeys.every((key) => !(key in advancedConstraint)),
    )

    await track.applyConstraints({
      ...currentConstraints,
      advanced: [...preservedAdvanced, constraint as MediaTrackConstraintSet],
    })
  } catch {
    // Optional camera controls vary by Android device and WebView version.
  }
}

function waitForCameraFocus(delay = 701): Promise<void> {
  return new Promise((resolve) => {
    window.setTimeout(resolve, delay)
  })
}

function waitForVideoReady(video: HTMLVideoElement): Promise<void> {
  if (video.videoWidth > 0 && video.videoHeight > 0) {
    return Promise.resolve()
  }

  return new Promise((resolve, reject) => {
    const timeoutId = window.setTimeout(() => {
      cleanup()
      reject(new Error('Camera video did not become ready.'))
    }, 3000)

    const handleReady = () => {
      if (video.videoWidth > 0 && video.videoHeight > 0) {
        cleanup()
        resolve()
      }
    }

    const cleanup = () => {
      window.clearTimeout(timeoutId)
      video.removeEventListener('loadedmetadata', handleReady)
      video.removeEventListener('canplay', handleReady)
    }

    video.addEventListener('loadedmetadata', handleReady)
    video.addEventListener('canplay', handleReady)
  })
}

function groupCollection(
  items: CollectionItem[],
  groupBy: CollectionGroup,
  sortBy: CollectionSort,
) {
  const groups = new Map<string, CollectionItem[]>()

  for (const item of sortCollectionItems(items, sortBy)) {
    const label = getCollectionGroupLabel(item, groupBy)
    const groupItems = groups.get(label) ?? []
    groupItems.push(item)
    groups.set(label, groupItems)
  }

  return Array.from(groups.entries())
    .map(([label, groupItems]) => ({
      label,
      items: groupItems,
      distinctCards: countDistinctCollectionCards(groupItems),
      value: groupItems.reduce(
        (total, item) => total + (item.priceUsd ?? 0) * item.quantity,
        0,
      ),
    }))
    .sort((left, right) => left.label.localeCompare(right.label))
}

function getCoachRecommendationGroups(
  recommendation: CoachRecommendation,
  game: GameFilter,
  collection: CollectionItem[],
): CoachRecommendationGroup[] {
  const explicitGroups = recommendation.groups
    ?.filter((group) => group.cards.length > 0)
    .map((group) => ({
      ...group,
      cards: [...group.cards].sort((left, right) =>
        left.name.localeCompare(right.name),
      ),
    }))

  if (explicitGroups?.length) {
    return explicitGroups
  }

  if (recommendation.add.length < 9) {
    return []
  }

  const collectionByName = new Map(
    collection
      .filter((item) => item.game === game)
      .map((item) => [normalizeCardName(item.name), item]),
  )
  const groups = new Map<string, CoachRecommendationGroup>()

  for (const card of recommendation.add) {
    const item = collectionByName.get(normalizeCardName(card.name))
    const label = item ? getCollectionGroupLabel(item, 'color') : 'Other'
    const group = groups.get(label) ?? {
      label,
      totalQuantity: 0,
      distinctCards: 0,
      cards: [],
    }
    group.cards.push(card)
    group.totalQuantity += card.quantity
    group.distinctCards = group.cards.length
    groups.set(label, group)
  }

  return Array.from(groups.values())
    .map((group) => ({
      ...group,
      cards: [...group.cards].sort((left, right) =>
        left.name.localeCompare(right.name),
      ),
    }))
    .sort((left, right) => left.label.localeCompare(right.label))
}

function sortCollectionItems(items: CollectionItem[], sortBy: CollectionSort) {
  return [...items].sort((left, right) => {
    if (sortBy === 'value') {
      return (right.priceUsd ?? 0) * right.quantity - (left.priceUsd ?? 0) * left.quantity
    }

    if (sortBy === 'quantity') {
      return right.quantity - left.quantity
    }

    if (sortBy === 'newest') {
      return new Date(right.addedAt).getTime() - new Date(left.addedAt).getTime()
    }

    return left.name.localeCompare(right.name)
  })
}

function getCollectionGroupLabel(item: CollectionItem, groupBy: CollectionGroup) {
  if (groupBy === 'set') {
    return item.setName || 'Unknown Set'
  }

  if (groupBy === 'condition') {
    return item.condition || 'Unknown Condition'
  }

  if (groupBy === 'category') {
    return item.category || 'Other'
  }

  if (item.game === 'pokemon') {
    return item.colors?.[0] ?? item.category ?? 'Pokemon'
  }

  return getMtgColorLabel(item)
}

function getMtgColorLabel(item: CollectionItem) {
  if (isMtgLand(item)) {
    return 'Land'
  }

  const colors = item.colors ?? []

  if (!colors.length) {
    return 'Colorless'
  }

  if (colors.length > 1) {
    return 'Multicolor'
  }

  const labels: Record<string, string> = {
    W: 'White',
    U: 'Blue',
    B: 'Black',
    R: 'Red',
    G: 'Green',
    C: 'Colorless',
  }

  return labels[colors[0]] ?? 'Other'
}

function isMtgLand(item: CollectionItem) {
  return /\bland\b/i.test(`${item.typeLine ?? ''} ${item.category ?? ''}`)
}

function groupMtgColorSectionItems(section: string, items: CollectionItem[]) {
  if (section === 'Multicolor') {
    return groupMtgItems(items, (item) =>
      getMtgColorCombinationLabel(item.colors ?? []),
    )
  }

  if (section === 'Land') {
    return groupMtgItems(items, getMtgLandColorLabel)
  }

  return groupMtgItems(items, getMtgCardTypeLabel, true)
}

function groupMtgItems(
  items: CollectionItem[],
  getLabel: (item: CollectionItem) => string,
  sortByLabel = false,
) {
  const groups = new Map<string, CollectionItem[]>()

  for (const item of items) {
    const label = getLabel(item)
    const groupItems = groups.get(label) ?? []
    groupItems.push(item)
    groups.set(label, groupItems)
  }

  return Array.from(groups.entries())
    .map(([label, groupItems]) => ({
      label,
      items: groupItems,
      distinctCards: countDistinctCollectionCards(groupItems),
      value: groupItems.reduce(
        (total, item) => total + (item.priceUsd ?? 0) * item.quantity,
        0,
      ),
      sortKey: sortByLabel
        ? label
        : getMtgColorCombinationSortKey(
            sectionColorsForSort(groupItems[0], label),
          ),
    }))
    .sort((left, right) => left.sortKey.localeCompare(right.sortKey))
}

function countDistinctCollectionCards(items: CollectionItem[]) {
  return new Set(items.map((item) => normalizeCardName(item.name))).size
}

function formatDistinctCardCount(count: number) {
  return `${count} different card${count === 1 ? '' : 's'}`
}

function getMtgLandColorLabel(item: CollectionItem) {
  const colors = (item.colorIdentity ?? item.colors ?? []).filter((color) =>
    ['W', 'U', 'B', 'R', 'G'].includes(color),
  )

  if (!colors.length) {
    return 'Colorless'
  }

  return getMtgColorCombinationLabel(colors)
}

function getMtgCardTypeLabel(item: CollectionItem) {
  const typeLine = `${item.typeLine ?? ''} ${item.category ?? ''}`.toLowerCase()

  if (typeLine.includes('artifact creature')) {
    return 'Artifact Creatures'
  }

  const labels: Array<[string, string]> = [
    ['artifact', 'Artifacts'],
    ['creature', 'Creatures'],
    ['planeswalker', 'Planeswalkers'],
    ['enchantment', 'Enchantments'],
    ['instant', 'Instants'],
    ['sorcery', 'Sorceries'],
    ['battle', 'Battles'],
  ]

  return labels.find(([type]) => typeLine.includes(type))?.[1] ?? 'Other'
}

function groupDeckEditorEntries(
  entries: DeckEditorEntry[],
  game: GameFilter,
  commanderName = '',
) {
  const groups = new Map<string, DeckEditorEntry[]>()
  const commanderKey = normalizeCardName(commanderName)

  for (const value of entries) {
    const item = value.item
    let label = 'Other'

    if (
      game === 'mtg' &&
      commanderKey &&
      normalizeCardName(item.name) === commanderKey
    ) {
      label = 'Commander'
    } else if (game === 'mtg') {
      label = isMtgLand(item) ? 'Lands' : getMtgCardTypeLabel(item)
    } else if (game === 'pokemon') {
      const typeText = `${item.category ?? ''} ${item.typeLine ?? ''}`.toLowerCase()

      if (typeText.includes('energy')) {
        label = 'Energy'
      } else if (typeText.includes('trainer')) {
        const trainerTypes: Array<[string, string]> = [
          ['supporter', 'Trainer - Supporters'],
          ['stadium', 'Trainer - Stadiums'],
          ['tool', 'Trainer - Tools'],
          ['item', 'Trainer - Items'],
        ]
        label =
          trainerTypes.find(([type]) => typeText.includes(type))?.[1] ??
          'Trainers'
      } else {
        label = 'Pokemon'
      }
    }

    const group = groups.get(label) ?? []
    group.push(value)
    groups.set(label, group)
  }

  const order = [
    'Commander',
    'Pokemon',
    'Creatures',
    'Artifact Creatures',
    'Planeswalkers',
    'Artifacts',
    'Enchantments',
    'Instants',
    'Sorceries',
    'Battles',
    'Trainer - Items',
    'Trainer - Supporters',
    'Trainer - Stadiums',
    'Trainer - Tools',
    'Trainers',
    'Energy',
    'Lands',
    'Other',
  ]

  return Array.from(groups.entries())
    .map(([label, groupEntries]) => ({
      label,
      entries: groupEntries,
      quantity: groupEntries.reduce(
        (total, value) => total + value.entry.quantity,
        0,
      ),
    }))
    .sort((left, right) => {
      const leftIndex = order.indexOf(left.label)
      const rightIndex = order.indexOf(right.label)
      const leftOrder = leftIndex === -1 ? order.length : leftIndex
      const rightOrder = rightIndex === -1 ? order.length : rightIndex
      return leftOrder - rightOrder || left.label.localeCompare(right.label)
    })
}

function sectionColorsForSort(item: CollectionItem | undefined, label: string) {
  if (!item) {
    return []
  }

  if (isMtgLand(item)) {
    return item.colorIdentity ?? item.colors ?? []
  }

  if (label === 'Colorless') {
    return []
  }

  return item.colors ?? []
}

function getMtgColorCombinationLabel(colors: string[]) {
  const labels: Record<string, string> = {
    W: 'White',
    U: 'Blue',
    B: 'Black',
    R: 'Red',
    G: 'Green',
  }
  const orderedColors = ['W', 'U', 'B', 'R', 'G'].filter((color) =>
    colors.includes(color),
  )

  return orderedColors.map((color) => labels[color]).join(' / ') || 'Other'
}

function getMtgColorCombinationSortKey(colors: string[]) {
  const orderedColors = ['W', 'U', 'B', 'R', 'G'].filter((color) =>
    colors.includes(color),
  )

  return `${orderedColors.length}-${orderedColors
    .map((color) => ['W', 'U', 'B', 'R', 'G'].indexOf(color))
    .join('')}`
}

export default App
